/** The policy a volume is created under. Only `data-local` exists so far: persistent, one writer, on the member's own pool; moving it means stopping the instance. */
export type VolumeClass = "data-local";

/** What the volume holds: a mounted filesystem or a raw disk (virtual machines only). */
export type VolumeContent = "filesystem" | "block";

export type VolumeItem = {
  appliance: string;
  class: string;
  content: string;
  createdAt: string;
  /** The Incus volume (`<instance>-<name>`): what to type to delete it. */
  incusName: string;
  instance: string;
  /** Member of a member-local pool; empty on a standalone server. */
  member: string;
  /** The design's name (`data`). */
  name: string;
  pool: string;
  sizeMib: number;
  state: VolumeUse;
  /** Instances using it. */
  usedBy: string[];
};

/** A volume an appliance asks for. */
export type VolumeMount = {
  class?: VolumeClass;
  content?: VolumeContent;
  /** Name in the design, e.g. `data`: lowercase letters, digits and `-`, at most 16. */
  name: string;
  /** Where a filesystem volume is mounted inside the instance; none for a block volume. */
  path?: string | null;
  /** The pool the class resolves to. Set by the control plane, never by a caller. */
  pool?: string | null;
  sizeMib: number;
};

/** What Incus reports about a recorded volume now. */
export type VolumeUse = "attached" | "retained" | "missing";

export type WhoAmI = {
  /** Permission ids held at some scope (what the UI may offer; the server decides each request). */
  capabilities: string[];
  /** Incus projects this control plane deploys into (`APELORA_DEPLOY_PROJECTS`). */
  deployProjects: string[];
  /** The user or service identity id; absent for legacy tokens. */
  id?: string | null;
  /** `user` (OIDC sign-in), `service` (automation identity), `legacy-token` or `development`. */
  kind: string;
  name: string;
  /** What the older, coarse permissions amount to for this caller at platform level. */
  permissions: Permission[];
  /** Permission ids held across the whole platform. */
  platformPermissions: string[];
  role?: null | Role;
  /** The role assignments in force for this caller. */
  roles: RoleGrant[];
};

