/** Success body of each operation (`null` for 204 No Content). */
export type Responses = {
  /** Applications the caller may see, each with design status, derived runtime status, replica health, and the actions they may take now. Needs `application.view`. */
  applications: ApplicationList;
  /** Creates an application in an environment, optionally with its first draft. Needs `application.create` on the environment's project. */
  create_application: ApplicationInfo;
  /** One application with its appliances (desired and observed), versions and recent operations. Needs `application.view`. */
  application: ApplicationDetail;
  /** Changes an application's description or icon (its name cannot change). Needs `application.design`. */
  update_application: ApplicationInfo;
  /** What the caller may open on each instance of the application now, with the reason when not. This is the source for the interface's menu entries. Needs `application.view`. */
  application_access: AccessList;
  /** Archives an application that is not running; it leaves the default list and keeps its data. Needs `application.delete`. */
  archive_application: null;
  /** Deploys the design: saves it as a new revision and queues the planned changes. Refuses the whole deployment if any appliance conflicts with an existing instance. Needs `deploy`. */
  deploy_application: DeployResponse;
  /** The application's working document. 404 when it has none yet. Needs `application.view`. */
  application_draft: DraftDto;
  /** Saves the draft as the next version. Refused with 409 `draft_conflict` (and the current version) when someone saved since `baseVersion`; nothing is overwritten. Needs `application.design`. */
  save_application_draft: DraftDto;
  /** What happened to the application: creation, saves, versions, deployments, operations, refusals. Needs `application.view`. */
  application_events: AuditList;
  /** Opens a session: checks the caller, the instance and the approval rule, and answers with a single-use ticket for the websocket. Needs `instance.console` (terminal, PowerShell) or `instance.desktop` (RDP) on the application; in production also an approval (`Apelora-Approval: <id>`) of `instance.console` on `instance:<application>/<instance>`. */
  open_session: SessionTicket;
  /** Recent operations of the application, newest first. Needs `application.view`. */
  application_operations: OperationList;
  /** Starts, stops or restarts the application's instances, in dependency order, as an asynchronous operation. Succeeds only when Incus confirms each instance's state. Needs `application.operate` on the application. It only touches instances this application owns; networks, volumes, data and other applications are left alone. */
  operate_application: OperationAccepted;
  /** One operation with the progress of each phase and instance. Needs `application.view`. */
  application_operation: OperationDto;
  /** What deploying the design would change, without changing anything. Needs `deploy`. */
  plan_application: Plan;
  /** Brings an archived application back. Needs `application.delete`. */
  restore_application: null;
  /** The application's instances as Incus reports them, by appliance. Needs `read-inventory`. */
  application_status: ApplicationStatus;
  /** Versions of the application, newest first. Needs `application.view`. */
  application_versions: VersionList;
  /** Releases the current draft as the next immutable published version. Refused while the draft is invalid or when this draft version is already published. Needs `application.design`. */
  publish_application: VersionInfo;
  /** The document of one version. Needs `application.view`. */
  application_version: VersionDocument;
  /** The application's volumes, with what Incus says about each now. Needs `application.view`. */
  application_volumes: ApplicationVolumes;
  /** Deletes one of the application's volumes and its snapshots, for good. The volume's Incus name must be typed again; refused while an instance uses it. Needs `application.delete` (and an approval where the policy asks for one); audited. */
  delete_application_volume: null;
  /** Requests and approvals: your own, plus every open one if you may approve. Needs `approval.request` or `approval.grant`. */
  approvals: ApprovalList;
  /** Asks for approval of one risky action on one target. You must be allowed to do the action yourself; someone else with `approval.grant` then decides. Needs `approval.request`. */
  request_approval: ApprovalDto;
  /** Approves a request made by someone else. Needs `approval.grant`. The approval is good for 30 minutes, once. */
  approve_request: ApprovalDto;
  /** Withdraws your own pending request. Needs `approval.request`. */
  cancel_request: ApprovalDto;
  /** Rejects a request. Needs `approval.grant`. */
  reject_request: ApprovalDto;
  /** The most recent audit events the caller may read, newest first. Needs `audit.read` (platform-wide, or limited to the events of the caller's organisations, projects and applications) and a database. */
  audit: AuditList;
  /** The Incus server and its cluster members. Needs `read-inventory`. */
  cluster: ClusterResponse;
  /** Join tokens waiting to be used (no secrets). Needs `manage-infrastructure`. */
  list_join_tokens: JoinTokenList;
  /** Approves a new cluster member: asks Incus for a single-use join token. Needs `manage-infrastructure`. The token is in this response only. */
  create_join_token: JoinTokenCreated;
  /** Withdraws a new member's approval: revokes its unused join token. Needs `manage-infrastructure`. */
  revoke_join_token: null;
  /** Evacuates a cluster member through Incus after re-running the dry run: refused while anything blocks it. Needs `manage-infrastructure` and the admin identity; audited. */
  evacuate_member: MemberStateStarted;
  /** Dry run of evacuating a cluster member: per instance, what Incus will do and what it means for the application; what blocks it; what to accept. Changes nothing. */
  preview_evacuation: EvacuationPreview;
  /** Restores an evacuated member: Incus moves its instances back and starts them. Needs `manage-infrastructure` and the admin identity; audited. */
  restore_member: MemberStateStarted;
  /** Public. Reports the service, the inventory provider, the authentication mode and whether Incus is reachable. */
  health: Health;
  /** Role assignments in the caller's scopes. Needs `user.view`. */
  assignments: AssignmentList;
  /** Grants a role to a person, group or automation identity at a scope. Needs `role.assign` there and every permission the role holds (no escalation); audited. */
  create_assignment: AssignmentDto;
  /** Shows what an assignment would give before it is saved: what the person can already do at the scope, what they could do afterwards, which permissions would be inert, and whether you may save it. Changes nothing. Needs `role.assign`. */
  preview_assignment: AssignmentPreview;
  /** Revokes an assignment; the person loses it on their next request. Needs `role.assign` in its scope. The last platform super admin cannot be revoked. */
  revoke_assignment: null;
  /** Audit history the caller may read, filtered and paged. Needs `audit.read`. */
  identity_audit: AuditList;
  /** Grants a person a platform role for a short time, with a recorded reason (break-glass). You cannot grant it to yourself; every request made with it is audited. Needs `platform.emergency_access`. */
  grant_emergency_access: AssignmentDto;
  /** Groups the caller may see. Needs `user.view`. */
  groups: GroupList;
  /** Creates a group: an organisation's (needs `group.manage` there) or a platform group (platform `group.manage`). Mapping a group to an identity-provider group name is platform-only. */
  create_group: GroupDto;
  /** Members of a group. Needs `user.view` or `group.manage` on the group's organisation. */
  group_members: UserList;
  /** Adds a person to a group. Needs `group.manage`. */
  add_group_member: null;
  /** Removes a person from a group; their access through it ends on their next request. Needs `group.manage`. */
  remove_group_member: null;
  /** Organisations the caller may see. Needs `organization.view` (or a grant below that reaches them). */
  organizations: OrganizationList;
  /** Creates an organisation. Needs `organization.create` (platform). */
  create_organization: OrganizationDto;
  /** Creates a project in an organisation. Needs `project.create` on the organisation. */
  create_project: ProjectDto;
  /** Every permission, its class and the narrowest scope at which a grant takes effect. */
  permissions: PermissionList;
  /** Access policies (MFA and approval rules). Needs `access_policy.manage` or `audit.read`. */
  policies: PolicyList;
  /** Creates or updates a policy by name. `mfa`: `{"environments": ["production"], "infrastructure": true}`. `approval`: `{"actions": ["cluster.evacuate"]}` (extra actions that need approval where the API already asks for it). Needs `access_policy.manage`. */
  save_policy: PolicyDto;
  /** Deletes a policy. Needs `access_policy.manage`. */
  delete_policy: null;
  /** Projects the caller may see, optionally of one organisation. Needs `project.view`. */
  projects_list: IdentityProjectList;
  /** Environments of a project. Needs `project.view` on it. */
  environments: EnvironmentList;
  /** Creates an environment. The Incus project it maps to is derived from the names (tenants cannot choose it); platform administrators may map an existing one. Needs `environment.manage`. */
  create_environment: EnvironmentDto;
  /** The predefined and custom roles with their permissions. */
  roles: RoleList;
  /** Defines a custom role from explicit permissions. Needs `role.manage` (platform), and you may only include permissions you hold yourself. */
  create_role: RoleDto;
  /** Deletes a custom role that no assignment uses. Needs `role.manage`. */
  delete_role: null;
  /** Registered service identities (the credentials Apelora uses for Incus and MAAS, and automation identities that call this API). Needs `service_identity.manage`. */
  service_identities: ServiceIdentityList;
  /** Registers a service identity. Outbound kinds (workload, network, storage, provisioning) record only the name of a credential held in the secret store; automation identities get an API token, shown once. Needs `service_identity.manage`. */
  create_service_identity: ServiceIdentityCreated;
  /** Disables a service identity at once. Needs `service_identity.manage`. */
  disable_service_identity: null;
  /** Re-enables a service identity. Needs `service_identity.manage`. */
  enable_service_identity: null;
  /** People who have signed in, as far as the caller may see them: everyone for a platform administrator, otherwise those with a role in the caller's scopes. Needs `user.view`. */
  users: UserList;
  /** Finds one person by exact user name or e-mail so a role can be given to them. Someone who has never signed in does not exist yet. Needs `role.assign` or `group.manage`. */
  lookup_user: UserList;
  /** Disables a person: their tokens stop working at once. Needs `user.manage`. */
  disable_user: null;
  /** Re-enables a person. Needs `user.manage`. */
  enable_user: null;
  /** Instances in all projects. Needs `read-inventory`. */
  instances: InstanceList;
  /** Queues creation of an instance. Needs `deploy`. Apelora marks it as its own; only such instances can later be stopped or deleted through Apelora. */
  create_instance: JobAccepted;
  /** Queues deletion of an Apelora instance (stopped first if running). Needs `deploy`. */
  delete_instance: JobAccepted;
  /** Queues starting or stopping an Apelora instance. Needs `deploy`. */
  change_state: JobAccepted;
  /** The 100 most recent jobs, newest first. Needs `read-inventory`. */
  jobs: JobList;
  /** A queued job and its progress. Needs `read-inventory`. */
  job: Job;
  /** Machines being enrolled, with their state derived from Incus. Needs `manage-infrastructure`. */
  list_machines: MachineList;
  /** Registers a machine. A name that is already an eligible member is adopted as admitted. Needs `manage-infrastructure`; audited. */
  register_machine: Machine;
  /** Forgets a machine that is not a cluster member (revoking an unused join token). Needs `manage-infrastructure`; audited. */
  remove_machine: null;
  /** The admission checks for a joined machine (dry run; changes nothing). Needs `manage-infrastructure`. */
  machine_admission: Admission;
  /** Admits a joined machine: re-runs the admission checks and, when none fails, lets Incus place instances on it. Needs `manage-infrastructure`; audited. */
  admit_machine: Admission;
  /** Withdraws an approval: revokes the machine's unused join token. Needs `manage-infrastructure`; audited. */
  withdraw_machine_approval: null;
  /** Approves a machine: asks Incus for its single-use join token, returned only in this response with the command to run on the server. Needs `manage-infrastructure`; audited without the token. */
  approve_machine: MachineApproved;
  /** Networks in all projects. Needs `read-inventory`. */
  networks: NetworkList;
  /** Read-only readiness checks of the Incus server or cluster and of the projects Apelora deploys into. Changes nothing. Needs `read-inventory`. */
  preflight: PreflightReport;
  /** Incus projects. Needs `read-inventory`. */
  projects: ProjectList;
  /** Open sessions the caller started, and those on applications they may operate. */
  sessions: SessionList;
  /** Ends a session now. Allowed for the person who has it and for whoever may operate its application. Anything else answers 404. */
  terminate_session: null;
  /** Storage pools. Needs `read-inventory`. */
  storage_pools: StoragePoolList;
  /** Versions of this control plane and the Incus release it is pinned to, and when the certificates Apelora uses to reach Incus expire. Needs `read-inventory`. The running Incus version is in `/api/v1/health`. */
  system: SystemInfo;
  /** API tokens, active and revoked (never the tokens themselves). Needs `manage-tokens`. */
  tokens: TokenList;
  /** Creates an API token, shown only in this response. Needs `manage-tokens`. */
  create_token: TokenCreated;
  /** Revokes an API token; it stops working at once. Needs `manage-tokens`. */
  revoke_token: null;
  /** Who is calling, with the role assignments and permissions in force. */
  whoami: WhoAmI;
};

